/**
 * Common contracts, descriptors, and helpers shared across scholarly tools.
 * @module dsh-zotero/scholarly/tools/common
 */

import type { Context } from '@deepseek-ai/cordis'
import type { JsonValue } from '@deepseek-ai/dsh-util-values'
import type { SpillRef } from '@deepseek-ai/dsh-spill'
import { spilledNoticeOf } from '../../spill.js'
import type { ScholarlyHttp } from '../transport/http.js'
import type { ScholarlyKeys } from '../types.js'
import type { JobPolicy, ZoteroJobRunner } from '../../job-runner.js'
import type { ZoteroServiceLike } from '../zotero-link.js'
import type { FulltextEnhancer } from '../../local/fulltext-enhancer.js'
import type { EvidenceRanker } from '../../local/evidence-ranker.js'

export interface ScholarlyToolHost {
  http: ScholarlyHttp
  keys(): Promise<ScholarlyKeys>
  maxResults(): number
  jobPolicy(): JobPolicy
  jobRunner(): ZoteroJobRunner
  zoteroService?(): ZoteroServiceLike | undefined
  /** Optional higher-quality document parser from the enrichment component. */
  enrichmentEnhancer?(): FulltextEnhancer | undefined
  /**
   * The ranking strategy passage matching uses: the core's lexical ranker, or
   * the hybrid one the enrichment component installs. Required: without it,
   * `scholarly_read` and `zotero_retrieve` can rank the same paper by different
   * rules.
   */
  evidenceRanker(): EvidenceRanker
  /**
   * The chunk boundaries passage matching cuts on. Required: without them the
   * two tools would silently describe one paper with different passages.
   */
  evidenceChunkLimits(): { readonly chunkWords: number; readonly chunkChars: number }
  ctx?: Context
}

/** One bounded, model-readable Scholarly receipt. Text remains the human rendering. */
export const SCHOLARLY_TEXT_OUTPUT_DESCRIPTOR = {
  schema: {
    type: 'object',
    additionalProperties: false,
    properties: {
      text: { type: 'string', required: true },
      papers: { type: 'array', items: { type: 'object', additionalProperties: true } },
      citations: { type: 'array', items: { type: 'object', additionalProperties: true } },
      checks: { type: 'array', items: { type: 'object', additionalProperties: true } },
      document: { type: 'object', additionalProperties: true },
      issues: { type: 'array', items: { type: 'string' } },
      spill: {
        type: 'object',
        additionalProperties: false,
        properties: {
          locator: { type: 'string', required: true },
          bytes: { type: 'integer', required: true },
          retrievalHint: { type: 'string', required: true },
        },
      },
    },
  },
  render: (
    _args: unknown,
    value: {
      text: string
      spill?: { readonly locator: string; readonly bytes: number; readonly retrievalHint: string }
    },
  ) => {
    const text = value.text
    // A result whose body does not already carry the handle gets the
    // persisted-spill notice: the complete content is at the locator, and the
    // byte count is stated in the harness spelling a spill-aware reader knows.
    const recovery =
      value.spill !== undefined && !text.includes(value.spill.locator)
        ? spilledNoticeOf(value.spill, value.spill.bytes)
        : ''
    return [{ type: 'text' as const, text: `${text}${recovery}` }]
  },
} as const

export type ScholarlyToolOutput = {
  text: string
  papers?: Array<Record<string, JsonValue>>
  citations?: Array<Record<string, JsonValue>>
  checks?: Array<Record<string, JsonValue>>
  document?: Record<string, JsonValue>
  issues?: string[]
  spill?: SpillRef
}

/**
 * Recursively clean an object into pure JsonValue by removing undefined entries.
 */
function toCleanJsonValue(value: unknown): JsonValue {
  if (
    value === null ||
    typeof value === 'string' ||
    typeof value === 'number' ||
    typeof value === 'boolean'
  ) {
    return value
  }
  if (Array.isArray(value)) {
    return value.filter((v) => v !== undefined).map(toCleanJsonValue)
  }
  if (typeof value === 'object') {
    const res: Record<string, JsonValue> = {}
    for (const [k, v] of Object.entries(value)) {
      if (v !== undefined) {
        res[k] = toCleanJsonValue(v)
      }
    }
    return res
  }
  return null
}

export function toCleanJsonRecord<T extends object>(item: T): Record<string, JsonValue> {
  return toCleanJsonValue(item) as Record<string, JsonValue>
}

export function toCleanJsonRecords<T extends object>(
  items: readonly T[],
): Array<Record<string, JsonValue>> {
  return items.map(toCleanJsonRecord)
}
